from pathlib import Path
from html import escape
import shutil
out=Path(__file__).parent/'dist'
(out/'assets').mkdir(parents=True,exist_ok=True)
shutil.copyfile(out.parents[1]/'Aitist_Milli_20261109/02-compact.png',out/'assets/milli.png')
mark='<svg viewBox="0 0 262 192" aria-hidden="true"><path fill="currentColor" d="M0 192 68 55 129 55 61 192ZM104 0H167L227 123H164ZM102 133H232L262 192H102Z"/></svg>'
logo=f'<a class="logo" href="/" aria-label="aitist home">{mark}<span>aitist</span></a>'
def page(title,body,active=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="aitist develops efficient inference systems to bring AI within everyone’s reach."><title>{escape(title)} · aitist</title><link rel="stylesheet" href="/assets/site.css"></head><body class="{'journal' if active else 'home'}"><script src="/assets/motion.js" defer></script>{'<script src="/assets/wordmark.js" defer></script>' if not active else ''}<a class="skip" href="#main">Skip to content</a><header class="wrap top">{logo}<nav aria-label="Main"><a href="/#approach">Approach</a><a href="/blog/" {'aria-current="page"' if active else ''}>Research notes</a></nav><a class="contact" href="mailto:contact@aitist.ai">Contact <span>↗</span></a></header><main id="main">{body}</main><footer class="wrap foot">{logo}<p>Bring AI within everyone’s reach.</p><a href="/blog/">Research notes ↗</a></footer></body></html>'''
def put(path,title,body,active=''):
    f=out/path/'index.html'
    f.parent.mkdir(parents=True,exist_ok=True)
    f.write_text(page(title,body,active))
art='<svg viewBox="0 0 460 380" class="heroart" role="img" aria-label="Three modular pieces form the aitist A on a technical grid"><defs><pattern id="grid" width="23" height="23" patternUnits="userSpaceOnUse"><path d="M23 0H0V23" fill="none" stroke="white" opacity=".19"/></pattern></defs><rect x="0" y="0" width="460" height="368" fill="url(#grid)"/><path d="M230 0V368M0 184H460" stroke="white" opacity=".33" stroke-dasharray="4 6"/><g transform="translate(93 75) scale(1.05)" fill="white"><path class="part a" d="M0 192 68 55 129 55 61 192Z"/><path class="part b" d="M104 0H167L227 123H164Z"/><path class="part c" d="M102 133H232L262 192H102Z"/></g></svg>'
posts=[
('inference-efficiency','01','Inference','What does it mean to get more from every chip?','A framework for measuring inference efficiency across latency, throughput, and cost per completed task.',[
('Start with the workload','The unit of comparison is a workload. Fix the model, request mix, and quality requirements before comparing configurations. Record the hardware, concurrency, prompt length, and output length so a result can be interpreted in context.'),
('Measure the service','Track time to first token and time per output token alongside throughput. Report tail latency at the target load. A higher token rate is useful when requests still finish within the service’s latency budget.'),
('Count completed work','Cost per completed task brings compute, retries, and quality into the same accounting. For a fixed workload, divide the serving cost by the number of requests that meet both the quality and latency criteria.'),
('Keep the evidence','Record the baseline, candidate, test conditions, and any regressions. Repeat the comparison before promoting the candidate. Use the accepted configuration as the baseline for the next round.')]),
('target-verify-compound','02','Method','Target, verify, compound','How a measurable objective becomes a repeatable loop for systems improvement.',[
('Define the target','Write down the workload and the metric before proposing changes. Set the constraints that protect correctness, latency, and service behavior.'),
('Verify independently','Run the candidate and baseline under comparable conditions. Repeat measurements where variance could change the conclusion, and retain the configuration and test inputs with the result.'),
('Promote and repeat','Promote candidates that satisfy the constraints and improve the target. Keep a rollback path and use the newly verified baseline for the next experiment.')])]
def research_art(tag):
    if tag == 'Inference':
        layers = ''.join(f'<g class="layer" data-depth="{i+1}" transform="translate(0 {y})"><path d="M170 0H440L510 70H240Z" fill="white" stroke="black"/><path d="M197 0L267 70M224 0L294 70M251 0L321 70M278 0L348 70M305 0L375 70M332 0L402 70M359 0L429 70M386 0L456 70M413 0L483 70M193 23H463M217 47H487" stroke="black" stroke-width=".55"/></g>' for i,y in enumerate((164,106,48)))
        return f'<svg viewBox="0 0 680 270" role="img" aria-label="Three stacked grids illustrate layers of inference measurement">{layers}</svg>'
    return '<svg viewBox="0 0 680 270" role="img" aria-label="Target, verify and compound connected in a loop"><path d="M170 138H510M510 163V213H170V163" stroke="black" fill="none" stroke-dasharray="4 5"/><g fill="white" stroke="black"><circle cx="170" cy="138" r="32"/><circle cx="340" cy="138" r="32"/><circle cx="510" cy="138" r="32"/></g><g text-anchor="middle" font-family="monospace"><text x="170" y="144">01</text><text x="340" y="144">02</text><text x="510" y="144">03</text><text x="170" y="83">TARGET</text><text x="340" y="83">VERIFY</text><text x="510" y="83">COMPOUND</text></g></svg>'
def research_card(post):
    slug, _, tag, title, _, _ = post
    return (
        f'<a class="research-card" href="/blog/{slug}/">'
        f'<img src="/assets/{slug}.jpg" width="1536" height="1024" alt="" loading="lazy" decoding="async">'
        f'<div class="research-copy"><p class="mono">{tag}</p><h3>{title}</h3></div>'
        '<span class="research-arrow" aria-hidden="true">↗</span></a>'
    )
def research_grid():
    return '<div class="research-grid">' + ''.join(map(research_card, posts)) + '</div>'
