for slug,num,tag,title,desc,sections in posts:
    toc=''.join(f'<li><a href="#section-{i}">{name}</a></li>' for i,(name,_) in enumerate(sections,1))
    copy=''.join(f'<section id="section-{i}"><span class="mono">0{i}</span><h2>{name}</h2><p>{paragraph}</p></section>' for i,(name,paragraph) in enumerate(sections,1))
    put(Path('blog')/slug,title,f'''<div class="wrap paper"><a class="back" href="/blog/">← All research notes</a><header class="article-heading"><h1>{title}</h1><p class="byline">aitist</p><p class="mono article-meta">{tag} · Sample research note</p></header><figure class="articleart">{research_art(tag)}<figcaption class="mono">FIG. 01 / {"INFERENCE MEASUREMENT" if tag == "Inference" else "VERIFICATION LOOP"}</figcaption></figure><div class="reading"><aside><span class="mono">ON THIS PAGE</span><ol>{toc}</ol></aside><article><div class="abstract"><span class="mono">ABSTRACT</span><p>{desc}</p></div>{copy}<a class="more" href="/blog/">Back to research notes ↗</a></article></div></div>''','blog')
